using System;using System.IO;using System.Reflection;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;
public static class StudioIntegerNativeValidation {
 public static void Run(){try{Validate();UnityEditor.EditorApplication.Exit(0);}catch(Exception e){UnityEngine.Debug.LogException(e);UnityEditor.EditorApplication.Exit(1);}}

 public static void Validate(){ToolChannelPane pane=null;try{int value=0;pane=ToolChannelPane.Open("Integer Scrub Validation",()=>{value=ToolChannelPane.IntParameter("Integer Native Validation","Count",new GUIContent("Subdivisions"),0,0,32);},initialSize:new Vector2(340,150));pane.position=new Rect(200,200,340,150);void Draw(){pane.SendEvent(new Event{type=EventType.Layout});pane.SendEvent(new Event{type=EventType.Repaint});}void Send(EventType type,float delta=0){pane.SendEvent(new Event{type=type,button=0,mousePosition=new Vector2(30,36),delta=new Vector2(delta,0)});}Draw();int checks=0;foreach(float multiplier in new[]{.1f,1f,2f,4f}){typeof(ToolChannelPane).GetField("dragSensitivity",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(pane,multiplier);ToolChannelPane.SetFloatDefault("Integer Native Validation","Count",0);Draw();Send(EventType.MouseDown);Send(EventType.MouseDrag,12f/multiplier-1);if(value!=0)throw new Exception("Integer stepped before pixel threshold "+multiplier+" value="+value);checks++;Send(EventType.MouseDrag,1);if(value!=1)throw new Exception("Integer missed pixel threshold "+multiplier+" value="+value);checks++;Send(EventType.MouseDrag,-12f/multiplier);if(value!=0)throw new Exception("Integer reversal failed "+multiplier);checks++;Send(EventType.MouseUp);}File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../integer-native-result.txt")),"PASS "+checks+" native label-scrub assertions at 0.1x, 1x, 2x and 4x");}finally{if(pane)pane.Close();}}
}
